gm_login=apis.gmail.login(username='jefsmith@gmail.com', password=creds['gmail']);
access_token_gm=gm_login['access_token'];
print('gmail token obtained')

# phone contacts (parents) already fetched earlier; re-fetch quickly to be safe
ph_login=apis.phone.login(username='3272301258', password=creds['phone']);
access_token_ph=ph_login['access_token'];

contacts=[]
for rel in ['mother','father','parent']:
    page_index=0
    while True:
        resp=apis.phone.search_contacts(access_token=access_token_ph, query='', relationship=rel, page_index=page_index, page_limit=20)
        if not resp:
            break
        contacts.extend(resp)
        page_index+=1
        if page_index>50:
            break

# deduplicate by email
seen=set(); uniq=[]
for c in contacts:
    if c.get('email') in seen:
        continue
    seen.add(c.get('email'))
    uniq.append(c)

parents=[c for c in uniq if c.get('email')]
print('parents phone contacts:', [(p.get('first_name'), p.get('last_name'), p.get('email'), p.get('relationships')) for p in parents])

# Map each parent to Gmail user via search_users by email exact match
mapped=[]
for p in parents:
    email=p['email']
    page_index=0
    results=[]
    while True:
        resp=apis.gmail.search_users(query=email, page_index=page_index, page_limit=20)
        if not resp:
            break
        results.extend(resp)
        page_index+=1
        if page_index>50:
            break
    print('Search for', email, 'returned', len(results))
    exact=[r for r in results if r.get('email','').lower()==email.lower()]
    print('Exact email matches:', len(exact), '->', [(r.get('first_name'), r.get('last_name'), r.get('email')) for r in exact])
    if len(exact)==1:
        mapped.append(exact[0])
    elif len(exact)>1:
        print('AMBIGUITY UNRESOLVED for', email, ':', len(exact), 'candidates, EXCLUDING.')
    else:
        print('No exact Gmail user match for', email, 'EXCLUDING.')

print('mapped gmail users:', [(m.get('first_name'), m.get('last_name'), m.get('email')) for m in mapped])

